"use client";

import type { Evidence, ExplainView } from "@/src/lib/api";
import { categoryLabel, EvidenceBadge, StatusBadge } from "@/src/components/badges";
import { ScoreWaterfall } from "@/src/components/ScoreWaterfall";
import { FindingCard } from "@/src/components/FindingCard";
import { AssumptionItem, OfferCheckBox } from "@/src/components/DetailBlocks";
import { DecisionPanel } from "@/src/components/DecisionPanel";
import { AuditTrail } from "@/src/components/AuditTrail";
import { ProductContext } from "@/src/components/ProductContext";

const H2 = "text-xs font-semibold uppercase tracking-[0.16em] text-[var(--grey-500)]";

function numberOrDash(value: number | null | undefined, suffix = "") {
  return typeof value === "number" ? `${value.toLocaleString("en-US")}${suffix}` : "not available";
}

// Keep the proposal, priority chart and decision together before the evidence details.
export function RequirementDetailView({
  detail,
  evidenceBySignal,
  ignoreAssumptions,
  onToggleIgnoreAssumptions,
  onRefresh,
  scenarioId,
}: {
  detail: ExplainView;
  evidenceBySignal: Map<string, Evidence[]>;
  ignoreAssumptions: boolean;
  onToggleIgnoreAssumptions: (value: boolean) => void;
  onRefresh: () => Promise<void>;
  scenarioId: string;
}) {
  const { requirement } = detail;
  const business = detail.business ?? requirement.business;
  const conflicts = detail.conflicts ?? requirement.segment_conflicts ?? [];
  const webSources = detail.web_sources ?? [];
  const hasMoreContext = Boolean(detail.robustness_sentence || business || webSources.length || requirement.offer_check);

  return (
    <div className="grid gap-8">
      <header className="requirement-summary border-b border-[var(--hairline)] pb-6">
        <div className="summary-intro min-w-0">
          <p className={H2}>
            Rank {requirement.rank} · {categoryLabel(requirement.category)} · Score {requirement.score.toFixed(1)}
          </p>
          <h1 className="mt-3 text-2xl font-medium leading-tight text-[var(--ink)] sm:text-3xl">{requirement.title}</h1>
          <div className="mt-5 flex flex-wrap items-center gap-4">
            <EvidenceBadge level={requirement.evidence_level} reason={requirement.rationale} />
            <StatusBadge status={requirement.status} />
          </div>
          <p className="mt-5 max-w-2xl text-[var(--grey-500)]">{requirement.rationale}</p>
          <dl className="mt-5 grid grid-cols-2 gap-4 border-y border-[var(--hairline)] py-4 text-sm">
            <div><dt className="text-xs text-[var(--grey-500)]">Engineering effort</dt><dd className="mt-1 font-semibold">{({ S: "Small", M: "Medium", L: "Large" })[requirement.effort]} / preliminary estimate</dd></div>
            <div><dt className="text-xs text-[var(--grey-500)]">Planning horizon</dt><dd className="mt-1 font-semibold">{requirement.horizon === "next_gen" ? "Next generation" : "Current product"}</dd></div>
          </dl>
        </div>
        <div className="summary-chart min-w-0"><ScoreWaterfall scoreBreakdown={requirement.score_breakdown} evidenceLevel={requirement.evidence_level} finalScore={requirement.score} waterfall={detail.waterfall} ignoreAssumptions={ignoreAssumptions} onToggleIgnoreAssumptions={onToggleIgnoreAssumptions} /></div>
        <div className="summary-criterion min-w-0 border-l-2 border-[var(--blue)] bg-[var(--grey-100)] p-4">
          <p className={H2}>Success criterion</p>
          <p className="mt-2 text-sm font-medium text-[var(--ink)]">{requirement.acceptance_criterion}</p>
          <p className="mt-3 text-sm text-[var(--grey-500)]">{requirement.description}</p>
        </div>
        <div className="summary-decision min-w-0"><DecisionPanel requirement={requirement} onChanged={onRefresh} /></div>
      </header>

      <section>
        <div>
          <h2 className={H2}>What customers say · {detail.signals.length} findings</h2>
          <div className="mt-4 space-y-3">
            {detail.signals.length === 0 && <p className="border border-[var(--hairline)] p-3 text-sm text-[var(--grey-500)]">No findings linked.</p>}
            {detail.signals.map((signal) => (
              <div id={`signal-${signal.id}`} key={signal.id}>
                <FindingCard signal={signal} evidence={evidenceBySignal.get(signal.id) ?? []} />
              </div>
            ))}
          </div>
        </div>
      </section>

      <div className="grid gap-6 lg:grid-cols-2"><OfferCheckBox offerCheck={requirement.offer_check} /><ProductContext scenarioId={scenarioId} /></div>
      {business && <dl className="grid grid-cols-2 gap-4 border-y border-[var(--hairline)] py-4 sm:grid-cols-3">
        <div><dt className="text-xs text-[var(--grey-500)]">Market volume / 2025</dt><dd className="mt-1 text-xl tabular-nums">{numberOrDash(business.volume_2025)}</dd></div>
        <div><dt className="text-xs text-[var(--grey-500)]">Projected market volume / 2030</dt><dd className="mt-1 text-xl tabular-nums">{numberOrDash(business.volume_2030)}</dd></div>
        <div><dt className="text-xs text-[var(--grey-500)]">Projected growth / 2025 to 2030</dt><dd className="mt-1 text-xl tabular-nums">{numberOrDash(business.growth_pct, "%")}</dd></div>
      </dl>}

      <section>
        <h2 className={H2}>Assumptions and open questions</h2>
        <ul className="mt-4 grid gap-2 md:grid-cols-2">
          {requirement.assumptions.map((text, i) => <AssumptionItem key={`a-${i}`} label="Assumption" text={text} />)}
          {requirement.uncertainties.map((text, i) => <AssumptionItem key={`u-${i}`} label="Uncertainty" text={text} />)}
          {conflicts.map((conflict, i) => <AssumptionItem key={`c-${i}`} label="Conflicting evidence" text={conflict.statement} />)}
          {requirement.assumptions.length === 0 && requirement.uncertainties.length === 0 && conflicts.length === 0 && (
            <li className="border border-dashed border-[var(--hairline)] p-3 text-sm text-[var(--grey-500)]">No assumptions, uncertainties, or conflicts recorded.</li>
          )}
        </ul>
      </section>

      {hasMoreContext && (
        <details className="group border-y border-[var(--hairline)]">
          <summary className="cursor-pointer list-none py-4 text-sm font-semibold text-[var(--ink)] hover:text-[var(--blue)]">
            More context: robustness, business volume, web sources <span className="text-[var(--grey-500)] group-open:hidden">+</span>
          </summary>
          <div className="grid gap-6 pb-6">
            {detail.robustness_sentence && <p className="text-sm text-[var(--grey-500)]"><b className="text-[var(--ink)]">Robustness.</b> {detail.robustness_sentence}</p>}
            {business && (
              <p className="text-sm text-[var(--grey-500)]">
                <b className="text-[var(--ink)]">Business.</b> {numberOrDash(business.volume_2025)} vehicles in 2025, {numberOrDash(business.volume_2030)} in 2030,
                growth {numberOrDash(business.growth_pct, "%")}. {business.note}
              </p>
            )}
            {webSources.map((source) => (
              <article key={source.id} id={`evidence-${source.id}`} className="border border-[var(--hairline)] p-3 text-sm">
                <div className="flex flex-wrap items-center gap-2">
                  <span className="font-semibold text-[var(--ink)]">{source.publisher}</span>
                  <span className="border border-[var(--hairline)] px-2 py-0.5 text-xs text-[var(--grey-500)]">trust: {source.trust}</span>
                  {source.url && (
                    <a className="font-semibold text-[var(--blue)] underline underline-offset-2" href={source.url} target="_blank" rel="noopener noreferrer">Source link</a>
                  )}
                </div>
                <p className="mt-2 text-[var(--grey-500)]">{source.text}</p>
              </article>
            ))}
          </div>
        </details>
      )}

      <section>
        <h2 className={H2}>Decision record</h2>
        <div className="mt-4"><AuditTrail key={requirement.version + ":" + detail.history.length} requirementId={requirement.id} compact /></div>
      </section>
    </div>
  );
}
"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { getAudit, type AuditEvent } from "@/src/lib/api";

const LABELS: Record<string, string> = {
  PIPELINE_LOADED: "Data loaded", REQUIREMENT_PROPOSED: "Requirement proposed",
  REQUIREMENT_DISCARDED: "Draft excluded", PM_APPROVE: "Requirement approved",
  PM_REJECT: "Requirement rejected", PM_EDIT: "Requirement edited",
  PM_CHALLENGE: "Evidence challenged", AI_RESPONDED: "AI answered challenge",
  WEIGHTS_CHANGED: "Priorities recalculated", AI_LENS_SUGGESTED: "Priority preview suggested",
};

function display(value: unknown): string {
  if (value === null) return "Not recorded";
  if (typeof value === "object") return JSON.stringify(value, null, 2);
  return String(value);
}

function Changes({ payload }: { payload: Record<string, unknown> }) {
  const changes = Object.entries(payload).filter(([, value]) => value && typeof value === "object" && "before" in value && "after" in value);
  return <>
    {changes.length > 0 && <div className="mt-4 overflow-x-auto"><table className="w-full table-fixed text-left text-xs">
      <thead><tr className="border-b border-[var(--hairline)]"><th className="w-1/4 py-2">Changed field</th><th className="px-2 py-2">Before</th><th className="px-2 py-2">After</th></tr></thead>
      <tbody>{changes.map(([field, value]) => { const change = value as { before: unknown; after: unknown }; return <tr key={field} className="border-b border-[var(--hairline)] align-top"><th className="break-words py-3 font-medium">{field.replaceAll("_", " ")}</th><td className="px-2 py-3"><pre>{display(change.before)}</pre></td><td className="px-2 py-3"><pre>{display(change.after)}</pre></td></tr>; })}</tbody>
    </table></div>}
    {Object.keys(payload).length > 0 && <details className="mt-4 border-t border-[var(--hairline)] pt-3"><summary className="text-xs font-semibold">Full event data</summary><pre className="mt-3 max-h-72 overflow-auto text-xs text-[var(--grey-500)]">{JSON.stringify(payload, null, 2)}</pre></details>}
  </>;
}

export function AuditTrail({ scenarioId, requirementId, compact = false }: { scenarioId?: string; requirementId?: string; compact?: boolean }) {
  const [events, setEvents] = useState<AuditEvent[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadedFor, setLoadedFor] = useState("");
  const [query, setQuery] = useState("");
  const [actor, setActor] = useState("");
  const [type, setType] = useState("");
  const [order, setOrder] = useState("newest");
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const key = `${scenarioId ?? ""}:${requirementId ?? ""}`;
  useEffect(() => {
    let cancelled = false;
    getAudit({ scenarioId, requirementId }).then(next => {
      if (!cancelled) { setEvents(next); setError(null); setPage(0); setSelected(null); }
    }).catch((err: Error) => { if (!cancelled) setError(err.message); })
      .finally(() => { if (!cancelled) setLoadedFor(key); });
    return () => { cancelled = true; };
  }, [scenarioId, requirementId, key]);

  if (loadedFor !== key) return <p role="status" className="py-6 text-sm text-[var(--grey-500)]">Loading decision history...</p>;
  if (error) return <p role="alert" className="border border-rose-300 p-4 text-sm text-rose-800">{error}</p>;
  const filtered = events.filter(e => (!actor || e.actor.type === actor) && (!type || e.event_type === type)
    && `${LABELS[e.event_type] ?? e.event_type} ${e.rationale} ${e.requirement_id ?? ""} ${e.actor.name} ${e.seq} ${JSON.stringify(e.payload)}`.toLowerCase().includes(query.trim().toLowerCase()))
    .sort((a, b) => order === "newest" ? b.seq - a.seq : a.seq - b.seq);
  const size = compact ? 5 : 6;
  const pages = Math.max(1, Math.ceil(filtered.length / size));
  const currentPage = Math.min(page, pages - 1);
  const visible = filtered.slice(currentPage * size, (currentPage + 1) * size);
  const chosen = visible.find(e => e.seq === selected) ?? visible[0];
  const changeFilter = (set: (value: string) => void, value: string) => { set(value); setPage(0); setSelected(null); };
  return <section className="min-w-0">
    {!compact && <>
      <dl className="mb-6 grid grid-cols-3 gap-4 border-y border-[var(--hairline)] py-4">
        {[['human', 'PM actions'], ['ai', 'AI actions'], ['system', 'System actions']].map(([key, label]) => <div key={key}><dt className="text-xs text-[var(--grey-500)]">{label}</dt><dd className="mt-1 text-2xl tabular-nums">{events.filter(e => e.actor.type === key).length}</dd></div>)}
      </dl>
      <div className="mb-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <label className="field-label">Search history<input className="field-control" type="search" placeholder="Requirement, person or reason" value={query} onChange={e => changeFilter(setQuery, e.target.value)} /></label>
        <label className="field-label">Who acted<select className="field-control" value={actor} onChange={e => changeFilter(setActor, e.target.value)}><option value="">Everyone</option><option value="human">Product manager</option><option value="ai">AI</option><option value="system">System</option></select></label>
        <label className="field-label">Action<select className="field-control" value={type} onChange={e => changeFilter(setType, e.target.value)}><option value="">All actions</option>{[...new Set(events.map(e => e.event_type))].map(t => <option key={t} value={t}>{LABELS[t] ?? t.replaceAll("_", " ")}</option>)}</select></label>
        <label className="field-label">Order<select className="field-control" value={order} onChange={e => changeFilter(setOrder, e.target.value)}><option value="newest">Latest first</option><option value="oldest">Oldest first</option></select></label>
      </div>
    </>}
    <div className="mb-3 flex flex-wrap items-center justify-between gap-3 text-xs text-[var(--grey-500)]"><p role="status">{filtered.length} events{filtered.length !== events.length ? ` / ${events.length} total` : ""}</p>{(query || actor || type) && <button className="min-h-11 text-[var(--blue)]" onClick={() => { setQuery(""); setActor(""); setType(""); setPage(0); }}>Clear filters</button>}</div>
    {visible.length === 0 ? <p className="border-y border-[var(--hairline)] py-8 text-sm text-[var(--grey-500)]">No events match this selection.</p> : <div className={`grid min-w-0 gap-6 ${compact ? "" : "lg:grid-cols-[1fr_1.2fr]"}`}>
      <ol className="min-w-0 divide-y divide-[var(--hairline)] border-y border-[var(--hairline)]">
        {visible.map(e => <li key={e.seq}>
          <button aria-pressed={chosen?.seq === e.seq} onClick={() => setSelected(e.seq)} className={`w-full border-l-2 px-4 py-3 text-left ${chosen?.seq === e.seq ? "border-[var(--blue)] bg-blue-50" : "border-transparent hover:bg-[var(--grey-100)]"}`}>
            <span className="block text-sm font-semibold">{LABELS[e.event_type] ?? e.event_type.replaceAll("_", " ")}</span>
            <span className="mt-1 block text-xs text-[var(--grey-500)]">#{e.seq} / {new Date(e.ts).toLocaleString("en", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })} / {e.actor.name}</span>
            {e.requirement_id && <span className="mt-1 block break-words text-xs text-[var(--grey-500)]">{e.requirement_id}</span>}
          </button>
        </li>)}
      </ol>
      {chosen && <article className="min-w-0 self-start border-l-2 border-[var(--blue)] px-5 py-3" aria-label="Event details">
        <h3 className="text-lg font-medium">{LABELS[chosen.event_type] ?? chosen.event_type}</h3>
        <p className="mt-2 text-xs text-[var(--grey-500)]">{chosen.actor.type === "human" ? "Product manager" : chosen.actor.type === "ai" ? "AI" : "System"}: {chosen.actor.name} / {new Date(chosen.ts).toLocaleString("en")}</p>
        <p className="mt-4 text-xs font-semibold text-[var(--grey-500)]">Reason</p><p className="mt-1 break-words text-sm">{chosen.rationale}</p>
        {chosen.requirement_id && <Link href={`/requirements/${chosen.requirement_id}?scenario=${chosen.scenario_id}`} className="mt-4 inline-block text-sm font-semibold text-[var(--blue)]">Open requirement &rarr;</Link>}
        <Changes payload={chosen.payload} />
      </article>}
    </div>}
    {pages > 1 && <div className="mt-4 flex items-center justify-between gap-4 text-sm"><button className="min-h-11 px-3 disabled:opacity-40" disabled={currentPage === 0} onClick={() => { setPage(currentPage - 1); setSelected(null); }}>Previous</button><span className="tabular-nums">Page {currentPage + 1} of {pages}</span><button className="min-h-11 px-3 disabled:opacity-40" disabled={currentPage === pages - 1} onClick={() => { setPage(currentPage + 1); setSelected(null); }}>Next</button></div>}
  </section>;
}
"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { getScenarios } from "@/src/lib/api";
import { useLoad } from "@/src/lib/useLoad";
import { PageHeader, ErrorNote, Loading } from "@/src/components/ui/PageHeader";
import { ScenarioFilters, EMPTY_SCENARIO_FILTER, matchesScenario } from "@/src/components/ScenarioFilters";
import { ProductContext } from "@/src/components/ProductContext";

export default function ModelsPage() {
  const view = useLoad("models", getScenarios);
  const [filter, setFilter] = useState(EMPTY_SCENARIO_FILTER);
  const scenarios = view.data ?? [];
  const filtered = scenarios.filter(s => matchesScenario(s, filter));
  return <main className="mx-auto max-w-[1400px] px-6 py-10 lg:px-10">
    <PageHeader eyebrow="Vehicle selection" title="Models and markets" />
    <ScenarioFilters scenarios={scenarios} value={filter} onChange={setFilter} />
    {view.loading && <Loading what="models" />}
    {view.error && <ErrorNote message={view.error} />}
    {!view.loading && !view.error && <p role="status" className="my-5 text-sm text-[var(--grey-500)]">{filtered.length} of {scenarios.length} model and market combinations</p>}
    <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
      {filtered.map(s => <article key={s.id} className="flex min-w-0 flex-col overflow-hidden rounded border border-[var(--hairline)]">
        {s.derivative !== "G68" && <div className="relative aspect-[16/9] overflow-hidden bg-[var(--grey-100)]"><Image src={`/media/scenarios/${s.id}.jpg`} alt={s.model_name} fill sizes="(min-width: 1280px) 33vw, (min-width: 768px) 50vw, 100vw" className="object-cover" /></div>}
        {s.derivative === "G68" && <div className="flex aspect-[16/9] items-center justify-center bg-[var(--grey-100)] text-4xl font-light text-[var(--grey-500)]">{s.derivative}</div>}
        <div className="flex flex-1 flex-col p-5">
          <p className="text-xs text-[var(--grey-500)]">{s.derivative} / {s.market} / Successor {s.successor_horizon}</p>
          <h2 className="mt-2 text-xl font-medium">{s.model_name}</h2>
          <p className="my-4 text-sm text-[var(--grey-500)]">{s.data_coverage?.feedback.toLocaleString("en") ?? "Unavailable"} customer feedback records / {s.headline_numbers?.requirements ?? 0} requirements</p>
          <ProductContext scenarioId={s.id} />
          {s.warnings?.map(w => <p key={w} className="mt-3 text-xs text-amber-800">{w}</p>)}
          <Link href={`/cockpit?scenario=${s.id}`} className="mt-auto block pt-5 text-sm font-semibold text-[var(--blue)]">Open ranked requirements &rarr;</Link>
        </div>
      </article>)}
    </div>
    {!view.loading && !view.error && filtered.length === 0 && <p className="py-10 text-sm">No models match these filters.</p>}
  </main>;
}
"use client";

import { useState } from "react";
import type { Requirement } from "@/src/lib/api";
import { categoryLabel } from "../badges";
import { RequirementsTable } from "./RequirementsTable";

export function RequirementFilters(props: {
  requirements: Requirement[];
  previousRanks: Record<string, number>;
  highlightRanks: boolean;
  conflictTitles: (r: Requirement) => string[];
  scenarioId: string;
}) {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("");
  const [status, setStatus] = useState("");
  const [level, setLevel] = useState("");
  const [effort, setEffort] = useState("");
  const [order, setOrder] = useState("rank");
  const [conflicts, setConflicts] = useState(false);
  const filtered = props.requirements.filter(r =>
    `${r.title} ${r.description} ${r.id}`.toLowerCase().includes(query.toLowerCase().trim())
    && (!category || r.category === category) && (!status || r.status === status)
    && (!level || r.evidence_level === level) && (!effort || r.effort === effort)
    && (!conflicts || props.conflictTitles(r).length > 0 || Boolean(r.segment_conflicts?.length)))
    .sort((a, b) => order === "title" ? a.title.localeCompare(b.title) : order === "effort" ? ["S", "M", "L"].indexOf(a.effort) - ["S", "M", "L"].indexOf(b.effort) || a.rank - b.rank : a.rank - b.rank);
  const active = query || category || status || level || effort || conflicts;
  function clear() { setQuery(""); setCategory(""); setStatus(""); setLevel(""); setEffort(""); setConflicts(false); setOrder("rank"); }
  return <>
    <div className="mb-4 grid gap-3 sm:grid-cols-3 lg:grid-cols-6">
      <label className="field-label sm:col-span-3 lg:col-span-2">Search requirements<input className="field-control" type="search" placeholder="Title, topic or ID" value={query} onChange={e => setQuery(e.target.value)} /></label>
      <label className="field-label">Topic<select className="field-control" value={category} onChange={e => setCategory(e.target.value)}><option value="">All topics</option>{[...new Set(props.requirements.map(r => r.category))].map(c => <option key={c} value={c}>{categoryLabel(c)}</option>)}</select></label>
      <label className="field-label">Decision<select className="field-control" value={status} onChange={e => setStatus(e.target.value)}><option value="">All decisions</option>{["proposed", "challenged", "approved", "rejected"].map(s => <option key={s} value={s}>{s[0].toUpperCase() + s.slice(1)}</option>)}</select></label>
      <label className="field-label">Evidence<select className="field-control" value={level} onChange={e => setLevel(e.target.value)}><option value="">All evidence</option>{["A - Strong", "B - Moderate", "C - Weak", "D - Assumption"].map(l => <option key={l} value={l[0]}>{l}</option>)}</select></label>
      <label className="field-label">Engineering effort<select className="field-control" value={effort} onChange={e => setEffort(e.target.value)}><option value="">All effort</option><option value="S">Small</option><option value="M">Medium</option><option value="L">Large</option></select></label>
    </div>
    <div className="mb-4 flex flex-wrap items-center justify-between gap-3 text-sm">
      <p role="status" className="text-[var(--grey-500)]">{filtered.length} of {props.requirements.length} requirements</p>
      <div className="flex flex-wrap items-center gap-4">
        <label className="flex min-h-11 items-center gap-2"><input type="checkbox" checked={conflicts} onChange={e => setConflicts(e.target.checked)} />Conflicting evidence</label>
        <select aria-label="Sort requirements" className="field-control !w-auto" value={order} onChange={e => setOrder(e.target.value)}><option value="rank">Priority first</option><option value="effort">Lowest effort first</option><option value="title">Title A-Z</option></select>
        <button type="button" disabled={!active && order === "rank"} onClick={clear} className="min-h-11 text-[var(--blue)] disabled:opacity-40">Clear filters</button>
      </div>
    </div>
    {filtered.length ? <RequirementsTable {...props} requirements={filtered} /> : <p className="border-y border-[var(--hairline)] py-10 text-sm">No requirements match these filters.</p>}
  </>;
}
"use client";

import { useLoad } from "@/src/lib/useLoad";
import { getProductContext } from "@/src/lib/insights";

export function ProductContext({ scenarioId }: { scenarioId: string }) {
  const view = useLoad(scenarioId, () => getProductContext(scenarioId));
  const data = view.data;
  const price = (value: number) => new Intl.NumberFormat("en", { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(value);
  return <section className="border-y border-[var(--hairline)] py-4">
    <div className="flex flex-wrap items-baseline justify-between gap-3">
